    memoVisualOrder(ids){const set=new Set(ids),out=[];for(const token of this.canvas.memoOrder||[]){if(token.startsWith('e:')){const id=token.slice(2);if(set.has(id))out.push(id);}else if(token.startsWith('s:')){const sec=this.canvas.memoSections[token.slice(2)];for(const id of sec?.itemIds||[])if(set.has(id))out.push(id);}}for(const id of ids)if(!out.includes(id))out.push(id);return out;}
