    async dropMemoToSection(e,sid){e.preventDefault();e.stopPropagation();const ids=this.readMemoIds(e);if(!ids.length)return;const ordered=this.memoVisualOrder(ids);await this.mutate(c=>{const sec=c.memoSections[sid];if(!sec)return false;for(const id of ordered){const old=c.memoPlacements[id]?.sectionId;if(old&&c.memoSections[old])c.memoSections[old].itemIds=(c.memoSections[old].itemIds||[]).filter(x=>x!==id);c.memoOrder=(c.memoOrder||[]).filter(t=>t!==`e:${id}`);c.memoPlacements[id].sectionId=sid;}sec.itemIds=(sec.itemIds||[]).filter(x=>!ids.includes(x));sec.itemIds.push(...ordered);return true;});}
    async dropMemoUngrouped(e){e.preventDefault();const ids=this.readMemoIds(e);if(ids.length){const ordered=this.memoVisualOrder(ids);await this.mutate(c=>{for(const id of ordered){const old=c.memoPlacements[id]?.sectionId;if(old&&c.memoSections[old])c.memoSections[old].itemIds=(c.memoSections[old].itemIds||[]).filter(x=>x!==id);c.memoPlacements[id].sectionId=null;c.memoOrder=(c.memoOrder||[]).filter(t=>t!==`e:${id}`);c.memoOrder.push(`e:${id}`);}return true;});return;}const sid=e.dataTransfer.getData('application/x-chatgpt-net-section');if(sid)await this.reorderSection(sid,null);}
    async dropMemoBeforeSection(e,sid){e.preventDefault();e.stopPropagation();const ids=this.readMemoIds(e);if(!ids.length)return;const ordered=this.memoVisualOrder(ids);await this.mutate(c=>{for(const id of ordered){const old=c.memoPlacements[id]?.sectionId;if(old&&c.memoSections[old])c.memoSections[old].itemIds=(c.memoSections[old].itemIds||[]).filter(x=>x!==id);c.memoPlacements[id].sectionId=null;}let order=(c.memoOrder||[]).filter(t=>!ids.some(id=>t===`e:${id}`)),idx=order.indexOf(`s:${sid}`);if(idx<0)idx=order.length;order.splice(idx,0,...ordered.map(id=>`e:${id}`));c.memoOrder=order;return true;},{validateRoutes:false});}
    async dropMemoBefore(e,targetId){e.preventDefault();e.stopPropagation();const ids=this.readMemoIds(e);if(!ids.length||ids.includes(targetId))return;const ordered=this.memoVisualOrder(ids);await this.mutate(c=>{const targetMp=c.memoPlacements[targetId],section=targetMp?.sectionId;if(section){const arr=c.memoSections[section].itemIds||[];for(const id of ordered){const old=c.memoPlacements[id]?.sectionId;if(old&&c.memoSections[old])c.memoSections[old].itemIds=(c.memoSections[old].itemIds||[]).filter(x=>x!==id);c.memoOrder=(c.memoOrder||[]).filter(t=>t!==`e:${id}`);c.memoPlacements[id].sectionId=section;}const clean=arr.filter(x=>!ids.includes(x)),idx=clean.indexOf(targetId);clean.splice(Math.max(0,idx),0,...ordered);c.memoSections[section].itemIds=clean;}else{for(const id of ordered){const old=c.memoPlacements[id]?.sectionId;if(old&&c.memoSections[old])c.memoSections[old].itemIds=(c.memoSections[old].itemIds||[]).filter(x=>x!==id);c.memoPlacements[id].sectionId=null;}let order=(c.memoOrder||[]).filter(t=>!ids.includes(t.slice(2))),idx=order.indexOf(`e:${targetId}`);order.splice(Math.max(0,idx),0,...ordered.map(id=>`e:${id}`));c.memoOrder=order;}return true;});}
    beginNewSection(){const input=document.createElement('input');input.type='text';input.placeholder='分隔标题';input.className='cgn-memo-item';this.memoList.prepend(input);input.focus();let done=false;const finish=async commit=>{if(done)return;done=true;const title=input.value.trim();input.remove();if(commit&&title)await this.mutate(c=>{const sid=U.uuid();c.memoSections[sid]={sectionId:sid,title,collapsed:false,itemIds:[],createdAt:U.now(),modifiedAt:U.now()};c.memoOrder=(c.memoOrder||[]);c.memoOrder.unshift(`s:${sid}`);return true;});};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();finish(true);}if(e.key==='Escape'){e.preventDefault();finish(false);}};input.onblur=()=>finish(true);}
