    openSearch(){if(!this.canvas)return;UI.modal('搜索当前对话',(p,close)=>{const row=UI.el('div','cgn-row'),input=document.createElement('input');input.type='search';input.placeholder='输入普通文字';row.append(input);p.append(row);const results=UI.el('div','cgn-results');p.append(results);const run=()=>{results.replaceChildren();const q=input.value.toLowerCase();if(!q)return;for(const e of Object.values(this.canvas.entities)){const hay=`${e.text}\n${e.originalText||''}`.toLowerCase();if(hay.includes(q)){const b=UI.el('button','cgn-result',e.text);b.onclick=()=>{close();this.locateEntity(e.entityId);};results.append(b);}}for(const sec of Object.values(this.canvas.memoSections)){if(sec.title.toLowerCase().includes(q)){const b=UI.el('button','cgn-result',`备忘录标题：${sec.title}`);b.onclick=()=>{close();if(sec.collapsed)sec.collapsed=false;this.render();setTimeout(()=>this.memoList.querySelector(`[data-section-id="${CSS.escape(sec.sectionId)}"]`)?.scrollIntoView({block:'center'}));this.persistView();};results.append(b);}}};input.oninput=run;input.focus();});}
    openSettings(){UI.modal('ChatGPT NET 设置',(p,close)=>{const note=UI.el('div','','备份文件包含 ChatGPT 对话摘录和正文定位信息。导出文件由 Firefox 保存到浏览器下载位置；扩展不会宣称可移动 Firefox 内部数据库。');note.style.marginBottom='10px';p.append(note);const row=UI.el('div','cgn-row'),cur=UI.el('button','cgn-btn','导出当前画布'),all=UI.el('button','cgn-btn','导出全部画布'),imp=UI.el('button','cgn-btn','导入备份');row.append(cur,all,imp);p.append(row);cur.onclick=()=>{if(!this.canvas)return;if(!confirm('备份文件包含 ChatGPT 对话摘录和正文定位信息。继续导出当前画布？'))return;U.downloadJson(`chatgpt-net-${this.canvas.conversationId}.json`,Schema.exportBundle([this.canvas],this.global));};all.onclick=async()=>{if(!confirm('备份文件包含 ChatGPT 对话摘录和正文定位信息。继续导出全部画布？'))return;if(this.canvas&&!this.conflict)await this.persistView();const r=await Store.exportAll();U.downloadJson('chatgpt-net-all.json',r.bundle);};imp.onclick=()=>this.importBackup(close);});}
    importBackup(close){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const f=input.files?.[0];if(!f)return;let b;try{b=JSON.parse(await f.text());if(!b||b.product!==C.PRODUCT||!C.IMPORT_BASELINES.includes(b.baseline)||b.schemaVersion!==C.SCHEMA_VERSION||!Array.isArray(b.canvases)||new Set(b.canvases.map(c=>c.conversationId)).size!==b.canvases.length||!b.canvases.every(c=>Schema.validateCanvas(c)&&Router.routeAll(c).ok)||(b.global&&!Schema.validateGlobal(b.global)))throw new Error();}catch{UI.toast('导入失败：文件损坏、存在非法布局或格式不受支持。现有数据未被修改。');return;}const decisions={};if(b.global)decisions.__global=confirm('备份包含全局默认颜色、侧栏宽度和画布/备忘录比例。\n确定：使用备份中的全局默认设置\n取消：保留当前全局默认设置')?'imported':'existing';for(const c of b.canvases){const existing=await Store.loadCanvas(c.conversationId);if(existing)decisions[c.conversationId]={choice:confirm(`对话 ${c.title||c.conversationId} 已有画布。\n确定：保留导入文件中的完整版本\n取消：保留现有完整版本`)?'imported':'existing',expectedRevision:existing.revision};else decisions[c.conversationId]={choice:'imported',expectedRevision:null};}try{await Store.importBundle(b,decisions);close();if(this.canvas&&decisions[this.canvas.conversationId]?.choice==='imported')await this.loadConversation(this.canvas.conversationId);UI.toast('导入完成。');}catch{UI.toast('导入失败，现有数据未被修改。');}};input.click();}
    startSplit(e){if(!this.canvas)return;e.preventDefault();const start=e.clientY,ratio=this.canvas.view.memoRatio,rect=this.main.getBoundingClientRect();const cleanup=()=>{window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true);window.removeEventListener('pointercancel',cancel,true);},move=ev=>{if(!this.splitDrag)return;const dy=ev.clientY-start;this.canvas.view.memoRatio=U.clamp(ratio-dy/rect.height,C.MIN_MEMO_RATIO,C.MAX_MEMO_RATIO);this.applyPaneRatio();},up=()=>{if(!this.splitDrag){cleanup();return;}cleanup();this.splitDrag=null;const g=U.deepClone(this.global);g.memoRatio=this.canvas.view.memoRatio;Store.saveGlobal(g).then(saved=>{this.global=saved;}).catch(()=>UI.toast(C.MESSAGES.SAVE_FAILED));this.persistView();},cancel=()=>{if(this.splitDrag){this.canvas.view.memoRatio=ratio;this.splitDrag=null;}cleanup();this.applyPaneRatio();};this.splitDrag={ratio,cleanup};window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true);window.addEventListener('pointercancel',cancel,true);}
