    onKeyDown(e){if(!this.enabled||!this.mounted||U.isEditable(e.target))return;if(e.key==='Escape'){if(this.drag||this.resize||this.box||this.pan||this.splitDrag||this.sidebarDrag){this.cancelTemporary();e.preventDefault();return;}this.canvasSelection.clear();this.memoSelection.clear();this.selectionPopup?.hide();this.syncSelectionUi();return;}if(e.ctrlKey&&!e.altKey&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?this.redo():this.undo();}}
